def dedent_lines(text, n):
    lines = text.split('\n')
    result_lines = []
    for line in lines:
        removed = 0
        idx = 0
        while idx < n and idx < len(line) and line[idx] == ' ':
            idx += 1
            removed += 1
        result_lines.append(line[removed:])
    return '\n'.join(result_lines)

