def wrap_break_long_words(text, width):
    words = text.split()
    lines = []
    current = ""
    for word in words:
        remaining = word
        while len(remaining) > width:
            if current:
                lines.append(current)
                current = ""
            lines.append(remaining[:width])
            remaining = remaining[width:]
        if current == "":
            current = remaining
        elif len(current) + 1 + len(remaining) <= width:
            current = current + " " + remaining
        else:
            lines.append(current)
            current = remaining
    if current:
        lines.append(current)
    return lines

